import { describe, expect, it } from 'vitest'
import {
  BROWSER_CLIENT_HOST_PAGE_RECONCILIATION_PROTOCOL_VERSION,
  BrowserClientHostAttachParams,
  BrowserClientHostCommandEvent,
  BrowserClientHostReady
} from './browser-client-host-protocol'

const inventoryPage = {
  authorityRuntimeId: 'runtime-old',
  authorityEpoch: 'epoch-old',
  browserHostClientId: 'host-a',
  browserHostGeneration: 2,
  browserPageId: 'page-a',
  pageHostGeneration: 3,
  browserProfileId: 'profile-a',
  executionHostKey: 'native:runtime-a:1',
  state: 'active' as const
}

/** Raw command input for the parser under test, including deliberately malformed shapes. */
type RawReconciliationCommand = { type: string } & Record<string, unknown>

const command = (reconciliationCommand: RawReconciliationCommand) => ({
  type: 'command' as const,
  authorityRuntimeId: 'runtime-a',
  authorityEpoch: 'epoch-new',
  browserHostClientId: 'host-a',
  browserHostGeneration: 4,
  pageCommandProtocolVersion: 1 as const,
  pageReconciliationProtocolVersion: 1 as const,
  browserPageId: 'page-a',
  pageHostGeneration: 5,
  commandSequence: 6,
  commandId: 'command-a',
  command: reconciliationCommand
})

describe('browser client-host reconciliation protocol', () => {
  it('negotiates reconciliation only beside commands and complete inventory', () => {
    expect(
      BrowserClientHostAttachParams.parse({
        authorityRuntimeId: 'runtime-a',
        browserHostClientId: 'host-a',
        hostCapabilities: ['webview'],
        pageCommandProtocolVersion: 1,
        pageInventoryProtocolVersion: 1,
        pageInventory: [inventoryPage],
        pageReconciliationProtocolVersion: BROWSER_CLIENT_HOST_PAGE_RECONCILIATION_PROTOCOL_VERSION
      })
    ).toMatchObject({ pageReconciliationProtocolVersion: 1 })
    expect(
      BrowserClientHostReady.parse({
        type: 'ready',
        authorityEpoch: 'epoch-new',
        browserHostGeneration: 4,
        pageCommandProtocolVersion: 1,
        pageInventoryProtocolVersion: 1,
        pageReconciliationProtocolVersion: 1
      })
    ).toMatchObject({ pageReconciliationProtocolVersion: 1 })

    for (const incomplete of [
      { pageCommandProtocolVersion: 1 },
      { pageInventoryProtocolVersion: 1, pageInventory: [inventoryPage] }
    ]) {
      expect(() =>
        BrowserClientHostAttachParams.parse({
          authorityRuntimeId: 'runtime-a',
          browserHostClientId: 'host-a',
          hostCapabilities: ['webview'],
          pageReconciliationProtocolVersion: 1,
          ...incomplete
        })
      ).toThrow('Browser page reconciliation requires command and inventory negotiation')
    }
  })

  it('decodes exact reclaim, close, and restore commands only after negotiation', () => {
    const previousAuthority = {
      authorityRuntimeId: 'runtime-a',
      authorityEpoch: 'epoch-old',
      browserHostClientId: 'host-a',
      browserHostGeneration: 2,
      pageHostGeneration: 3
    }
    const reconciliationCommands = [
      {
        type: 'reclaimPage',
        previousAuthority,
        browserProfileId: 'profile-a',
        executionHostKey: 'native:runtime-a:1'
      },
      { type: 'closePage', targetAuthority: previousAuthority },
      {
        type: 'restorePage',
        browserProfileId: 'profile-a',
        executionHostKey: 'native:runtime-a:1',
        url: 'https://remote.internal/'
      }
    ]

    for (const reconciliationCommand of reconciliationCommands) {
      expect(BrowserClientHostCommandEvent.parse(command(reconciliationCommand))).toMatchObject({
        pageReconciliationProtocolVersion: 1,
        command: reconciliationCommand
      })
      const unnegotiated = command(reconciliationCommand)
      delete (unnegotiated as { pageReconciliationProtocolVersion?: number })
        .pageReconciliationProtocolVersion
      expect(() => BrowserClientHostCommandEvent.parse(unnegotiated)).toThrow(
        'Browser page reconciliation command was not negotiated'
      )
    }
  })

  it('rejects stale reclaim authority and malformed restore inputs', () => {
    expect(() =>
      BrowserClientHostCommandEvent.parse(
        command({
          type: 'reclaimPage',
          previousAuthority: {
            authorityRuntimeId: 'runtime-a',
            authorityEpoch: 'epoch-new',
            browserHostClientId: 'host-a',
            browserHostGeneration: 2,
            pageHostGeneration: 3
          },
          browserProfileId: 'profile-a',
          executionHostKey: 'native:runtime-a:1'
        })
      )
    ).toThrow('Browser page reclaim requires an older authority epoch')
    expect(() =>
      BrowserClientHostCommandEvent.parse(
        command({
          type: 'restorePage',
          browserProfileId: '',
          executionHostKey: 'native:runtime-a:1'
        })
      )
    ).toThrow()
  })

  it.each([
    {
      type: 'createPage',
      browserProfileId: 'profile-a',
      executionHostKey: 'native:runtime-a:1'
    },
    { type: 'navigate', url: 'https://remote.internal/' }
  ])('leaves legacy $type commands unchanged', (legacyPageCommand) => {
    const legacyCommand = Object.fromEntries(
      Object.entries(command(legacyPageCommand)).filter(
        ([key]) => key !== 'pageReconciliationProtocolVersion'
      )
    )

    expect(BrowserClientHostCommandEvent.parse(legacyCommand)).toEqual(legacyCommand)
  })
})

import { describe, expect, it } from 'vitest'
import {
  buildPaneAgentIdentityEvidenceWire,
  isForegroundProcessProofFresh,
  resolveCanonicalPaneAgentIdentity,
  type ForegroundProcessProof
} from './pane-agent-identity-adapter'

const freshProof: ForegroundProcessProof = {
  agent: 'codex',
  processIncarnation: 'opaque-pid-token',
  authorityId: 'main:test',
  capturedAgeMs: 50,
  validForMs: 5_000
}

describe('per-pane coverage gate', () => {
  it('covers a pane from hook, launch, or sleeping-session evidence alone', () => {
    expect(
      resolveCanonicalPaneAgentIdentity({ hookAgent: 'claude', hookIsLive: true }).coverage
    ).toBe('covered')
    expect(resolveCanonicalPaneAgentIdentity({ completedHookAgent: 'claude' }).coverage).toBe(
      'covered'
    )
    expect(resolveCanonicalPaneAgentIdentity({ launchAgent: 'codex' }).coverage).toBe('covered')
    expect(resolveCanonicalPaneAgentIdentity({ sleepingSessionAgent: 'gemini' }).coverage).toBe(
      'covered'
    )
  })

  it('never covers a pane from a title, a sibling, or a bare foreground name', () => {
    expect(resolveCanonicalPaneAgentIdentity({ title: 'claude' }).coverage).toBe('uncovered')
    expect(
      resolveCanonicalPaneAgentIdentity({ siblingAgent: 'claude', allowSibling: true }).coverage
    ).toBe('uncovered')
    expect(resolveCanonicalPaneAgentIdentity({ foregroundAgent: 'codex' }).coverage).toBe(
      'uncovered'
    )
  })

  it('is computed from evidence, never from a platform or remote flag', () => {
    // The input deliberately has no platform/isRemote field to branch on; this pins that a
    // hook-covered pane resolves identically regardless of any caller-side host knowledge.
    const identity = resolveCanonicalPaneAgentIdentity({ hookAgent: 'claude', hookIsLive: true })
    expect(identity).toMatchObject({ agent: 'claude', source: 'live-hook', coverage: 'covered' })
  })
})

describe('process rung requires a host-stamped proof', () => {
  it('rejects a stale or malformed proof and accepts a fresh one', () => {
    expect(isForegroundProcessProofFresh(freshProof)).toBe(true)
    expect(isForegroundProcessProofFresh({ ...freshProof, capturedAgeMs: 6_000 })).toBe(false)
    expect(isForegroundProcessProofFresh({ ...freshProof, capturedAgeMs: -1 })).toBe(false)
    expect(isForegroundProcessProofFresh({ ...freshProof, validForMs: 0 })).toBe(false)
    expect(isForegroundProcessProofFresh({ ...freshProof, capturedAgeMs: Number.NaN })).toBe(false)
  })

  it('a bare foreground name cannot outrank launch; a proven process can', () => {
    const unproven = resolveCanonicalPaneAgentIdentity({
      launchAgent: 'claude',
      foregroundAgent: 'codex'
    })
    expect(unproven).toMatchObject({ agent: 'claude', source: 'launch' })

    const proven = resolveCanonicalPaneAgentIdentity({
      launchAgent: 'claude',
      foregroundAgent: 'codex',
      processProof: freshProof
    })
    expect(proven).toMatchObject({ agent: 'codex', source: 'process', coverage: 'covered' })
