    expect(
      server.attestCompatibilityAuthority({
        paneKey: PANE_KEY,
        launchTokenHash: createHash('sha256').update('launch-before-restart').digest('hex'),
        connectionId: 'ssh-target',
        terminalProvenance: 'current_runtime'
      })
