        launchTokenHash: createHash('sha256').update('launch-after-restart').digest('hex'),
        connectionId: 'ssh-target',
        terminalProvenance: 'restored'
      })
    ).toBeNull()
    expect(
      server.attestCompatibilityAuthority({
        paneKey: PANE_KEY,
