import { describe, expect, it, vi } from 'vitest'
import type { RpcClient } from '../../../transport/rpc-client'
import type { RpcResponse, RpcSuccess } from '../../../transport/types'
import { uploadMobileNativeChatImages } from './mobile-native-chat-image-attachment'

function ok(id: string, result: unknown): RpcSuccess {
  return { id, ok: true, result, _meta: { runtimeId: 'runtime-1' } }
}

function methodNotFound(id: string): RpcResponse {
  return {
    id,
    ok: false,
    error: { code: 'method_not_found', message: 'no' },
    _meta: { runtimeId: 'r' }
  }
}

function failed(id: string, message: string): RpcResponse {
  return { id, ok: false, error: { code: 'failed', message }, _meta: { runtimeId: 'r' } }
}

function clientWithResponses(responses: RpcResponse[]): Pick<RpcClient, 'sendRequest'> & {
  calls: { method: string; params: unknown }[]
} {
  const calls: { method: string; params: unknown }[] = []
  return {
    calls,
    sendRequest: vi.fn(async (method: string, params?: unknown) => {
      calls.push({ method, params })
      const response = responses.shift()
      if (!response) {
        throw new Error(`unexpected request: ${method}`)
      }
      return response
    })
  }
}

describe('uploadMobileNativeChatImages', () => {
  it('uploads the picked image and returns its host path + local preview uri, without any terminal.send', async () => {
    const client = clientWithResponses([
      methodNotFound('start'),
      ok('save', '/tmp/orca-attach.png')
    ])

    const result = await uploadMobileNativeChatImages('library', {
      client,
      getConnectionId: async () => 'conn-7',
      pickImages: vi.fn().mockResolvedValue([{ base64: 'AAAA', uri: 'file:///photo.jpg' }])
    })

    expect(result).toEqual([
      {
        path: '/tmp/orca-attach.png',
        previewUri: 'file:///photo.jpg'
      }
    ])
    // Native chat defers the paste to submit — nothing is sent to the terminal here.
    expect(client.calls.some((call) => call.method === 'terminal.send')).toBe(false)
    const saveCall = client.calls.find((c) => c.method === 'clipboard.saveImageAsTempFile')
    expect(saveCall?.params).toEqual({ contentBase64: 'AAAA', connectionId: 'conn-7' })
  })

  it('uploads all three selected images in picker order', async () => {
    const client = clientWithResponses([
      methodNotFound('start-a'),
      ok('save-a', '/tmp/a.png'),
      methodNotFound('start-b'),
      ok('save-b', '/tmp/b.png'),
      methodNotFound('start-c'),
      ok('save-c', '/tmp/c.png')
    ])

    const order: string[] = []
    async function* pickImages() {
      for (const image of [
        { base64: 'AAAA', uri: 'file:///a.jpg' },
        { base64: 'BBBB', uri: 'file:///b.jpg' },
        { base64: 'CCCC', uri: 'file:///c.jpg' }
      ]) {
        order.push(`read:${image.uri}`)
        yield image
      }
    }
    const result = await uploadMobileNativeChatImages('library', {
      client,
      getConnectionId: async () => 'conn-7',
      pickImages,
      onImageUploaded: (image) => order.push(`uploaded:${image.previewUri}`)
    })

    expect(result).toEqual([
      {
        path: '/tmp/a.png',
        previewUri: 'file:///a.jpg'
      },
      {
        path: '/tmp/b.png',
        previewUri: 'file:///b.jpg'
      },
      {
        path: '/tmp/c.png',
        previewUri: 'file:///c.jpg'
      }
    ])
    expect(order).toEqual([
      'read:file:///a.jpg',
      'uploaded:file:///a.jpg',
      'read:file:///b.jpg',
      'uploaded:file:///b.jpg',
      'read:file:///c.jpg',
      'uploaded:file:///c.jpg'
    ])
  })

  it('returns an empty array when the picker is cancelled and uploads nothing', async () => {
    const client = clientWithResponses([])

    const result = await uploadMobileNativeChatImages('library', {
      client,
      getConnectionId: async () => null,
      pickImages: vi.fn().mockResolvedValue([])
    })

    expect(result).toEqual([])
    expect(client.calls).toEqual([])
  })

  it('reports completed uploads before a later image fails', async () => {
    const client = clientWithResponses([
      methodNotFound('start-a'),
      ok('save-a', '/tmp/a.png'),
      methodNotFound('start-b'),
      failed('save-b', 'upload failed')
    ])
    const onImageUploaded = vi.fn()

    await expect(
      uploadMobileNativeChatImages('library', {
        client,
        getConnectionId: async () => null,
        pickImages: vi.fn().mockResolvedValue([
          { base64: 'AAAA', uri: 'file:///a.jpg' },
          { base64: 'BBBB', uri: 'file:///b.jpg' }
        ]),
        onImageUploaded
      })
    ).rejects.toThrow('upload failed')
    expect(onImageUploaded).toHaveBeenCalledOnce()
    expect(onImageUploaded).toHaveBeenCalledWith({
      path: '/tmp/a.png',
      previewUri: 'file:///a.jpg'
    })
  })

  it('falls back to an inline data uri for the preview when the picker omits a uri', async () => {
    const client = clientWithResponses([methodNotFound('start'), ok('save', '/tmp/x.png')])

    const result = await uploadMobileNativeChatImages('files', {
      client,
      getConnectionId: async () => null,
      pickImages: vi.fn().mockResolvedValue([{ base64: 'BBBB' }])
    })

    expect(result).toEqual([
      {
        path: '/tmp/x.png',
        previewUri: 'data:image/png;base64,BBBB'
      }
    ])
  })

  it('signals upload start only after a real image is picked', async () => {
    const onUploadStart = vi.fn()
    const cancelledClient = clientWithResponses([])
    await uploadMobileNativeChatImages('library', {
      client: cancelledClient,
      getConnectionId: async () => null,
      pickImages: vi.fn().mockResolvedValue([]),
      onUploadStart
    })
    expect(onUploadStart).not.toHaveBeenCalled()

    const client = clientWithResponses([methodNotFound('start'), ok('save', '/tmp/y.png')])
    await uploadMobileNativeChatImages('library', {
      client,
      getConnectionId: async () => null,
      pickImages: vi.fn().mockResolvedValue([{ base64: 'CCCC', uri: 'file:///y.jpg' }]),
      onUploadStart
    })
    expect(onUploadStart).toHaveBeenCalledTimes(1)
  })
})

import { describe, expect, it, vi } from 'vitest'
import type { RpcClient } from '../../../transport/rpc-client'
import type { RpcResponse, RpcSuccess } from '../../../transport/types'
import { pasteMobileNativeChatImagePaths } from './mobile-native-chat-image-send'
import { buildAgentTuiClearInputForText } from '../../../../../src/shared/agent-tui-input-clear'

function sendResult(accepted: boolean, id = 'send'): RpcSuccess {
  return { id, ok: true, result: { send: { accepted } }, _meta: { runtimeId: 'r' } }
}

function clientWithResponses(responses: RpcResponse[]): Pick<RpcClient, 'sendRequest'> & {
  calls: { method: string; params: Record<string, unknown> }[]
} {
  const calls: { method: string; params: Record<string, unknown> }[] = []
  return {
    calls,
    sendRequest: vi.fn(async (method: string, params?: unknown) => {
      calls.push({ method, params: params as Record<string, unknown> })
      const response = responses.shift()
      if (!response) {
        throw new Error(`unexpected request: ${method}`)
      }
      return response
    })
  }
}

describe('pasteMobileNativeChatImagePaths', () => {
  it.each([false, true])(
    'separates OMP references with following text: %s',
    async (followedByText) => {
      const client = clientWithResponses([sendResult(true), sendResult(true), sendResult(true)])
      await pasteMobileNativeChatImagePaths({
        client,
        terminal: 'term-1',
        agent: 'omp',
        deviceToken: null,
        imagePaths: ['/tmp/a.png', '/tmp/b.png'],
        followedByText
      })
      expect(client.calls.map((call) => call.params.text)).toEqual([
        '\x15',
        '\x1b[200~@/tmp/a.png\x1b[201~ ',
        `\x1b[200~@/tmp/b.png\x1b[201~${followedByText ? ' ' : ''}`
      ])
    }
  )

  it.each(['omp', null, undefined])('sends portable references for %s', async (agent) => {
    const client = clientWithResponses([sendResult(true), sendResult(true)])
    await pasteMobileNativeChatImagePaths({
      client,
      terminal: 'term-1',
      agent,
      deviceToken: null,
      imagePaths: ['/tmp/my image.png'],
      followedByText: true
    })
    expect(client.calls[1]?.params).toMatchObject({
      text: '\x1b[200~@"/tmp/my image.png"\x1b[201~ ',
      enter: false
    })
  })

  it('clears the input line, then pastes each path as a bracketed, non-submitting terminal.send with the mobile client tag', async () => {
    const client = clientWithResponses([
      sendResult(true),
      sendResult(true),
      sendResult(true),
      sendResult(true)
    ])

    const ok = await pasteMobileNativeChatImagePaths({
      client,
      agent: 'claude',
      terminal: 'term-1',
      deviceToken: 'device-9',
      imagePaths: ['/tmp/a.png', '/tmp/b.png', '/tmp/c.png'],
      followedByText: true
    })

    expect(ok).toBe(true)
    expect(client.calls).toHaveLength(4)
    // Leading Ctrl+U clears any stale input so a retry can't duplicate the image.
    expect(client.calls[0]).toEqual({
      method: 'terminal.send',
      params: {
        terminal: 'term-1',
        text: '\x15',
        enter: false,
        client: { id: 'device-9', type: 'mobile' }
      }
    })
    expect(client.calls[1]?.params.text).toBe('\x1b[200~/tmp/a.png\x1b[201~')
    expect(client.calls[2]?.params.text).toBe('\x1b[200~/tmp/b.png\x1b[201~')
    expect(client.calls[3]?.params.text).toBe('\x1b[200~/tmp/c.png\x1b[201~ ')
  })

  it('stops and reports failure as soon as a paste is rejected', async () => {
    // Clear accepted, first image paste rejected.
    const client = clientWithResponses([sendResult(true), sendResult(false)])

    const ok = await pasteMobileNativeChatImagePaths({
      client,
      agent: 'claude',
      terminal: 'term-1',
      deviceToken: null,
      imagePaths: ['/tmp/a.png', '/tmp/b.png'],
      followedByText: true
    })

    expect(ok).toBe(false)
    // Never attempts the second path after the first is rejected.
    expect(client.calls).toHaveLength(2)
    expect(client.calls[1]?.params.text).toBe('\x1b[200~/tmp/a.png\x1b[201~')
    expect(client.calls[0]?.params).not.toHaveProperty('client')
  })

  it('aborts rather than scheduling a write past the shared paste deadline', async () => {
    vi.useFakeTimers()
    try {
      const responses = [sendResult(true), sendResult(true), sendResult(true)]
      const calls: { timeoutMs: unknown }[] = []
      // Each write burns 10s, so the 15s sequence budget is spent by the third.
      const client = {
        sendRequest: vi.fn(async (_method: string, _params?: unknown, options?: unknown) => {
          calls.push({ timeoutMs: (options as { timeoutMs: number }).timeoutMs })
          vi.advanceTimersByTime(10_000)
          return responses.shift()!
        })
      }

      const ok = await pasteMobileNativeChatImagePaths({
        client,
        agent: 'claude',
        terminal: 'term-1',
        deviceToken: null,
        imagePaths: ['/tmp/a.png', '/tmp/b.png'],
        followedByText: true
      })

      expect(ok).toBe(false)
      // Clear + first image only; the second image is never written.
      expect(calls).toHaveLength(2)
      expect(calls[0]?.timeoutMs).toBe(15_000)
      // Positive-but-small remainder still gets the floor.
      expect(calls[1]?.timeoutMs).toBe(5_000)
    } finally {
      vi.useRealTimers()
    }
  })
})

describe('clearing a parked multi-line launch draft before the image paste', () => {
  it('leads with the caller-sized burst instead of one Ctrl+U', async () => {
    // One Ctrl+U kills only the LAST line, so the draft's earlier lines would
    // survive and ride along with the image as part of the prompt body.
    const client = clientWithResponses([sendResult(true), sendResult(true)])
