})

// A write counts as saved only once IndexedDB has committed it (the transaction's `complete`), not
// when its `put` is queued: a crash in between would otherwise lose a draft reported as saved.
import { afterEach, describe, expect, it, vi } from 'vitest'
import { createIndexedDbNativeChatComposerDraftStorage } from './native-chat-composer-draft-indexeddb'

type FakeTransaction = {
  oncomplete: (() => void) | null
  onerror: (() => void) | null
  onabort: (() => void) | null
  error: Error | null
  objectStore: () => FakeStore
  commit: () => void
}
type FakeStore = {
  put: (value: unknown, key: string) => object
  delete: (key: string) => object
  get: (key: string) => { result: unknown; onsuccess: (() => void) | null }
}

function fakeDatabase(): {
  factory: IDBFactory
  transactions: FakeTransaction[]
  puts: unknown[]
} {
  const transactions: FakeTransaction[] = []
  const puts: unknown[] = []
  const database = {
    objectStoreNames: { contains: () => true },
    transaction: () => {
      const store: FakeStore = {
        put: (value) => {
          puts.push(value)
          return {}
        },
        delete: () => ({}),
        get: () => {
          const request: { result: unknown; onsuccess: (() => void) | null } = {
            result: undefined,
            onsuccess: null
          }
          queueMicrotask(() => request.onsuccess?.())
          return request
        }
      }
      const transaction: FakeTransaction = {
        oncomplete: null,
        onerror: null,
        onabort: null,
        error: null,
        objectStore: () => store,
        commit: () => {}
      }
      transactions.push(transaction)
      return transaction
    }
  }
  const factory = {
    open: () => {
      const request: { result: typeof database; onsuccess: (() => void) | null } = {
        result: database,
        onsuccess: null
      }
      queueMicrotask(() => request.onsuccess?.())
      return request
    }
  }
  // oxlint-disable-next-line typescript/consistent-type-assertions -- SAFETY: a stand-in exposing only the calls the adapter makes.
  return { factory: factory as unknown as IDBFactory, transactions, puts }
}

const DRAFT = { text: 'unsent', images: [], savedAt: 1 }
const settledYet = async (promise: Promise<void>): Promise<boolean> => {
  let settled = false
  void promise.then(() => (settled = true))
  await new Promise((resolve) => setTimeout(resolve, 0))
  return settled
}

describe('the IndexedDB draft storage', () => {
  it('settles a write only when its transaction completes', async () => {
    const { factory, transactions, puts } = fakeDatabase()
    const write = createIndexedDbNativeChatComposerDraftStorage(factory).write('scope', DRAFT)

    expect(await settledYet(write)).toBe(false)
    expect(puts).toEqual([DRAFT])
    transactions[0]!.oncomplete?.()
    await expect(write).resolves.toBeUndefined()
  })

  it('settles a read-modify-write only when its transaction completes', async () => {
    const { factory, transactions, puts } = fakeDatabase()
    const update = createIndexedDbNativeChatComposerDraftStorage(factory).update(
      'scope',
      () => DRAFT
    )

    expect(await settledYet(update)).toBe(false)
    expect(puts).toEqual([DRAFT])
    transactions[0]!.oncomplete?.()
    await expect(update).resolves.toBeUndefined()
  })

  it('rejects a write whose transaction aborts, as on a full disk', async () => {
    const { factory, transactions } = fakeDatabase()
    const write = createIndexedDbNativeChatComposerDraftStorage(factory).write('scope', DRAFT)
    await new Promise((resolve) => setTimeout(resolve, 0))
    transactions[0]!.error = new Error('QuotaExceededError')
    transactions[0]!.onabort?.()

    await expect(write).rejects.toThrow('QuotaExceededError')
  })

  describe('through the draft store', () => {
    const loaded: { clearNativeChatComposerDraftsForTests: () => void }[] = []
    afterEach(() => {
      for (const store of loaded.splice(0)) {
        store.clearNativeChatComposerDraftsForTests()
      }
    })

    async function storeOn(factory: IDBFactory) {
      vi.resetModules()
      const storageModule = await import('./native-chat-composer-draft-storage')
      storageModule.setNativeChatComposerDraftStorageForTests(
        createIndexedDbNativeChatComposerDraftStorage(factory)
      )
      const store = await import('./native-chat-composer-draft-store')
      loaded.push(store)
      return { store, drafts: await import('./native-chat-draft-cache') }
    }

    it('reports a scope’s write settled true only at its transaction’s complete', async () => {
      const { factory, transactions } = fakeDatabase()
      const { store, drafts } = await storeOn(factory)
      // The stand-in has no reads, so the startup load fails and stays pending a retry: this is an
      // append before the load landed, which reads and writes the stored draft in one transaction.
      void store.hydrateNativeChatComposerDrafts()
      drafts.appendNativeChatDraftCache('agent-session:s1', 'returned by Stop')
      const settled = store.nativeChatComposerDraftWriteSettled('agent-session:s1')

      await new Promise((resolve) => setTimeout(resolve, 0))
      expect(await settledYet(settled.then(() => {}))).toBe(false)
      const write = transactions.at(-1)!
      write.oncomplete?.()
      await expect(settled).resolves.toBe(true)
    })

    it('reports false when the scope’s transaction aborts', async () => {
      const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})
      const { factory, transactions } = fakeDatabase()
      const { store, drafts } = await storeOn(factory)
      void store.hydrateNativeChatComposerDrafts()
      drafts.appendNativeChatDraftCache('agent-session:s1', 'returned by Stop')
      const settled = store.nativeChatComposerDraftWriteSettled('agent-session:s1')

      await new Promise((resolve) => setTimeout(resolve, 0))
      const write = transactions.at(-1)!
      write.error = new Error('QuotaExceededError')
      write.onabort?.()
      await expect(settled).resolves.toBe(false)
      warn.mockRestore()
    })
  })
})

import { act, createElement, useLayoutEffect } from 'react'
import { createRoot, type Root } from 'react-dom/client'
import type { NativeChatAttachmentOwner } from './native-chat-attachment-upload'
import type { NativeChatReservedAttachment } from './native-chat-session-attachment-drop'
import { useNativeChatComposerPaste } from './use-native-chat-composer-paste'

type HookApi = ReturnType<typeof useNativeChatComposerPaste>

/** Mirrors the composer's attachment list so tests can assert what the user sees. */
type FakeChip = { id: string; path: string; previewUrl?: string; pending: boolean }

export function createChipStore(): {
  chips: FakeChip[]
  begin: (previewUrl?: string) => string | null
  resolve: (id: string, path: string, connectionId?: string | null) => void
  reveal: (id: string, previewUrl?: string) => void
  drop: (id: string) => void
  connectionIds: (string | null | undefined)[]
} {
  const chips: FakeChip[] = []
  const connectionIds: (string | null | undefined)[] = []
  let counter = 0
  return {
    chips,
    connectionIds,
    reveal: (id, previewUrl) => {
      const chip = chips.find((candidate) => candidate.id === id)
      if (chip) {
        chip.previewUrl = previewUrl
      }
    },
    begin: (previewUrl) => {
      counter += 1
      const id = `chip-${counter}`
      chips.push({ id, path: '', previewUrl, pending: true })
      return id
    },
    resolve: (id, path, connectionId) => {
      const chip = chips.find((candidate) => candidate.id === id)
      if (chip) {
        chip.path = path
        chip.pending = false
      }
      connectionIds.push(connectionId)
    },
    drop: (id) => {
      const index = chips.findIndex((candidate) => candidate.id === id)
      if (index !== -1) {
        chips.splice(index, 1)
      }
    }
  }
}

type ProbeArgs = {
  targetKey?: string
  agent?: 'claude' | 'omp'
  disabled: boolean
  resolveAttachmentOwner: () => NativeChatAttachmentOwner
  attachResolvedPaths: (paths: string[], connectionId?: string | null) => void
  attachCopiedFiles: (paths: string[]) => void
  captureCopiedFiles: () => (reserved: NativeChatReservedAttachment[]) => Promise<void>
  beginPendingImageAttachment: (previewUrl?: string) => string | null
  resolvePendingImageAttachment: (id: string, path: string, connectionId?: string | null) => void
  revealPendingImageAttachment: (id: string, previewUrl?: string) => void
  dropPendingImageAttachment: (id: string) => void
  insertTypedText: (text: string) => boolean
  setNotice: (notice: string | null) => void
  onReady: (api: HookApi) => void
}

function Probe({ onReady, ...args }: ProbeArgs): null {
  const api = useNativeChatComposerPaste({ agent: 'claude', caret: 0, setCaret: () => {}, ...args })
  useLayoutEffect(() => onReady(api))
  return null
}

let root: Root | null = null

export function unmountPasteProbe(): void {
  root?.unmount()
  root = null
}

export async function renderProbe(args: {
  agent?: 'claude' | 'omp'
  disabled?: boolean
  resolveAttachmentOwner: () => NativeChatAttachmentOwner
  attachResolvedPaths?: (paths: string[], connectionId?: string | null) => void
  attachCopiedFiles?: (paths: string[]) => void
  /** Receives the chips a macOS paste reserved, once the clipboard shows they are files. */
  continueCopiedFiles?: (reserved: NativeChatReservedAttachment[]) => Promise<void>
  store?: ReturnType<typeof createChipStore>
  insertTypedText?: (text: string) => boolean
  setNotice?: (notice: string | null) => void
}): Promise<{
  latest: () => HookApi
  setDisabled: (disabled: boolean) => Promise<void>
  setTarget: (key: string) => Promise<void>
}> {
  const container = document.createElement('div')
  document.body.append(container)
  const store = args.store ?? createChipStore()
  let api: HookApi | null = null
  root = createRoot(container)
  let targetKey = 'session-1'
  const render = async (disabled: boolean): Promise<void> => {
    await act(async () => {
      root?.render(
        createElement(Probe, {
          targetKey,
          agent: args.agent ?? 'claude',
          disabled,
          resolveAttachmentOwner: args.resolveAttachmentOwner,
          attachResolvedPaths: args.attachResolvedPaths ?? (() => {}),
          attachCopiedFiles: args.attachCopiedFiles ?? (() => {}),
          captureCopiedFiles: () => args.continueCopiedFiles ?? (async () => {}),
          beginPendingImageAttachment: args.agent === 'omp' ? () => null : store.begin,
          resolvePendingImageAttachment: store.resolve,
          revealPendingImageAttachment: store.reveal,
          dropPendingImageAttachment: store.drop,
          insertTypedText: args.insertTypedText ?? (() => true),
          setNotice: args.setNotice ?? (() => {}),
          onReady: (next) => {
            api = next
          }
        })
      )
    })
  }
  await render(args.disabled ?? false)
  return {
    latest: () => {
      if (!api) {
        throw new Error('Probe did not render')
      }
      return api
    },
    setDisabled: render,
    setTarget: async (key) => {
      targetKey = key
      await render(false)
    }
  }
}

